// n8n Code node: "Normalize Submission"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Replaces BOTH the old "Edit Fields" node and the "A1 Validator" agent.
//
// The old Edit Fields read fields[N].value and wrote a field NAMED
// fields[N].label, which destroyed every value in the payload -- the defect that
// made the entire workflow route every submission to "Missing Fields".
//
// The old validator was an LLM asked to check that eight fields were non-empty,
// with the result detected by testing whether its prose contained the word
// "VALIDATED". That false-passes whenever the model writes "VALIDATED" while
// explaining what is missing. Required-field checking is deterministic, so it
// is done here in code: no tokens, no ambiguity, no false pass.
//
// Fields are matched BY LABEL, not by position, so reordering the form no
// longer silently shifts every column.

// Accepts BOTH intake shapes, because the same form reaches n8n two ways:
//
//   1. Tally webhook  -> body.data.fields[] = [{ label, type, value, options }]
//   2. Google Sheets  -> a flat row whose COLUMN HEADERS are the question labels
//
// Tally's sheet columns are the question labels, and the matcher below is
// label-based, so one MAP serves both. The sheet route matters because it needs
// no inbound connectivity: n8n polls Google outbound, so it works from
// localhost with no tunnel.
const item = $input.first().json || {};
const body = item.body || {};
const data = body.data || {};
const isWebhook = Array.isArray(data.fields);

// Sheet columns Tally or n8n own, which are not questions and must not be
// reported as unmatched form labels.
const META_COLUMNS = /^(row_number|submission[ _]?id|respondent[ _]?id|form[ _]?id|form[ _]?name|submitted[ _]?at|created[ _]?at|timestamp|status|output[ _]?link|citation[ _]?count|unverified[ _]?count|notes)$/i;

// -> [{ label, field }] where field is a Tally field object or a { value } shim
const entries = isWebhook
  ? data.fields
      .filter(Boolean)
      .map((f) => ({ label: String(f.label || f.key || f.title || ''), field: f }))
  : Object.keys(item)
      .filter((k) => !META_COLUMNS.test(k))
      .map((k) => ({ label: k, field: { value: item[k] } }));

// The Sheets Trigger supplies row_number, which is the only reliable key for
// updating the row Tally just wrote. On the webhook path there is no row yet.
const row_number = isWebhook ? '' : item.row_number === undefined ? '' : item.row_number;

// label pattern -> canonical name. First match wins, so ORDER IS LOAD-BEARING:
// the most specific labels must be tested first. "Head of Department" and
// "Departmental Project Guideline" both contain the word "department", so both
// have to be matched before any pattern that looks for a department/programme.
// Getting this order wrong silently drops fields, which is the same class of
// failure as the original workflow's label/value swap.
const MAP = [
  ['guideline_url',   /guideline|departmental\s*(project\s*)?(guide|format|template)|upload|attachment|\bfile\b/i],
  ['student_email',   /e-?mail/i],
  ['hod',             /\bhod\b|head\s*of\s*(the\s*)?depart/i],
  ['supervisor',      /supervisor/i],
  ['reg_number',      /reg(istration)?[^a-z]*(number|no)\b|matric|admission\s*number|student\s*(id|number)/i],
  ['student_name',    /(student|your|full|candidate)[^a-z]*name|^name$/i],
  ['project_title',   /(project|research|study|thesis|dissertation)\s*(title|topic)|^title$/i],
  ['faculty',         /faculty|\bcollege\b|school\s*of/i],
  ['institution',     /institution|university|polytechnic/i],
  ['programme',       /programme|\bprogram\b|course\s*of\s*study|^department\b/i],
  ['study_location',  /(study|research)\s*(location|site|setting|area)|^location/i],
  ['study_duration',  /(study|research|project)\s*duration|^duration|time\s*frame|timeline/i],
];

const REQUIRED = [
  ['project_title',  'Project Title'],
  ['programme',      'Programme of Study'],
  ['faculty',        'Faculty'],
  ['institution',    'Institution'],
  ['student_name',   'Student Full Name'],
  ['reg_number',     'Registration/Matriculation Number'],
  ['supervisor',     "Supervisor's Name"],
  ['hod',            'Head of Department (HOD) Name'],
];

// Reduce any Tally field value to a trimmed string.
//
// The trap: for DROPDOWN, MULTIPLE_CHOICE, CHECKBOXES and RANKING, Tally does
// NOT send the chosen text. It sends an array of option UUIDs, and a separate
// `options` array mapping id -> text:
//
//   { type: "DROPDOWN", value: ["e7bfbbc6-c2e6-..."],
//     options: [{ id: "e7bfbbc6-c2e6-...", text: "Medical Radiography" }] }
//
// Taking `value` at face value writes a UUID into the thesis. Resolve it.
// FILE_UPLOAD instead sends an array of objects carrying `url`.
function toValue(f) {
  const v = f ? f.value : null;
  if (v === null || v === undefined) return '';

  const opts = f && Array.isArray(f.options) ? f.options : null;
  const resolve = (x) => {
    if (opts) {
      const hit = opts.find((o) => o && o.id === x);
      if (hit) return String(hit.text === undefined ? '' : hit.text).trim();
    }
    // Not an option id (free-text "Other", or a plain value) — keep as-is.
    return String(x).trim();
  };

  if (Array.isArray(v)) {
    if (!v.length) return '';
    if (typeof v[0] === 'object' && v[0] !== null) {
      // file upload / signature: take the first attachment's URL
      return String(v[0].url || v[0].value || v[0].label || v[0].name || '').trim();
    }
    return v.map(resolve).filter(Boolean).join(', ');
  }
  if (typeof v === 'object') return String(v.url || v.value || v.label || '').trim();
  return resolve(v);
}

const out = {};
const unmatched = [];

for (const e of entries) {
  const value = toValue(e.field);
  if (!value) continue;
  const hit = MAP.find(([, re]) => re.test(e.label));
  if (hit) {
    if (!out[hit[0]]) out[hit[0]] = value;   // first non-empty match wins
  } else {
    unmatched.push(e.label);
  }
}

const missing_required = REQUIRED.filter(([k]) => !out[k]).map(([, human]) => human);

// A guideline value only counts if it is actually a fetchable URL.
const guideline_url = /^https?:\/\//i.test(out.guideline_url || '') ? out.guideline_url : '';

// The form asks for "Programme of Study" and prompts with "e.g. Bachelor of
// Radiography", so students type a DEGREE, not a department. The document needs
// both, in different places:
//
//   cover page  -> "DEPARTMENT OF RADIOGRAPHY"
//   title page  -> "...FOR THE AWARD OF BACHELOR OF RADIOGRAPHY"
//
// Blindly prefixing gives "Bachelor of Science in Bachelor of Radiography", and
// using the raw value as a department gives "DEPARTMENT OF BACHELOR OF
// RADIOGRAPHY". Derive the two separately.
// The trailing "(of|in)" must be allowed independently of "of science",
// otherwise "Bachelor of Radiography" strips only "Bachelor" and leaves
// "of Radiography" as the department name.
const DEGREE_LEAD =
  /^\s*(b\.?\s?sc\.?|m\.?\s?sc\.?|b\.?a\.?|m\.?a\.?|ph\.?\s?d\.?|b\.?[a-z]{2,4}\.?|bachelor(\s+of\s+science)?(\s+(of|in))?|master(\s+of\s+science)?(\s+(of|in))?|doctor(\s+of\s+philosophy)?(\s+(of|in))?|degree\s+in)\s+/i;

const LOOKS_LIKE_DEGREE =
  /^\s*(b\.?\s?sc|m\.?\s?sc|b\.?a\b|m\.?a\b|ph\.?\s?d|b\.?[a-z]{2,4}\b|bachelor|master|doctor)/i;

const programme = out.programme || '';
// Department: strip any leading degree phrase. "Bachelor of Radiography" ->
// "Radiography"; "Medical Radiography" is left alone.
const stripped = programme.replace(DEGREE_LEAD, '').trim();
const department = stripped || programme;
// Degree: already a degree title? use it verbatim. Otherwise name one.
const degree = !programme
  ? ''
  : LOOKS_LIKE_DEGREE.test(programme)
  ? programme
  : 'Bachelor of Science in ' + programme;

const now = new Date();
const monthYear =
  ['January','February','March','April','May','June','July','August','September','October','November','December'][now.getMonth()] +
  ' ' + now.getFullYear();

return [
  {
    json: {
      trigger_source: isWebhook ? 'webhook' : 'sheet',
      row_number,
      submission_id: String(
        data.submissionId || data.responseId || data.id ||
        item['Submission ID'] || item.submission_id ||
        (row_number !== '' ? 'row-' + row_number : '')
      ),
      created_at: String(
        data.createdAt || item['Submitted at'] || item.timestamp || now.toISOString()
      ),
      project_title: out.project_title || '',
      programme: out.programme || '',
      faculty: out.faculty || '',
      institution: out.institution || '',
      student_name: out.student_name || '',
      reg_number: out.reg_number || '',
      supervisor: out.supervisor || '',
      hod: out.hod || '',
      study_location: out.study_location || '',
      study_duration: out.study_duration || '',
      student_email: out.student_email || '',
      guideline_url,
      guideline_uploaded: guideline_url ? 'Yes' : 'No',
      department,
      degree,
      month_year: monthYear,
      missing_required,
      is_valid: missing_required.length === 0,
      unmatched_form_labels: unmatched,
    },
  },
];

// n8n Code node: "Clear Sheet Error"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Sheet writes are bookkeeping, not the deliverable, so "Sheet · Record
// Submission" runs with onError: continueRegularOutput -- a spreadsheet problem
// must not cost the student their thesis.
//
// The catch is that n8n does not simply carry on. The item that node emits has
// the failure attached to it (json.error plus an item-level error object), and
// n8n forwards an already-flagged item straight to the ERROR output of the next
// node that has one. Observed on execution 147: the sheet write failed on
// missing columns, and "Download Guideline" then fetched the PDF perfectly --
// 2.29 MB of real binary -- yet still reported on its error branch, because the
// item was condemned before it ever arrived.
//
// Rebuilding the item from the normalizer discards both the flag and the
// wreckage of the json, so a failed write stays where it happened and is
// recorded, instead of derailing every node downstream of it.
const clean = $('Normalize Submission').first().json;
const incoming = $input.first().json || {};
const err = incoming.error;

return [
  {
    json: {
      ...clean,
      // '' when the write succeeded. Surfaced so the run can report a partial
      // success later rather than claiming the sheet is up to date.
      sheet_write_error: err ? String(err.message || err) : '',
    },
    // Single item, and downstream nodes resolve $('Normalize Submission').item
    // through the paired-item chain -- breaking it here would break them.
    pairedItem: { item: 0 },
  },
];

// n8n Code node: "Normalize Format Rules"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Produces the format_rules object that drives the DOCX styles.
//
// In the original workflow the guideline was downloaded, parsed and analysed --
// and then thrown away: the analyzer fed a Merge node whose output nothing read,
// and the sub-workflow call forwarded only the validator's prose. This node is
// the convergence point that makes the guideline actually reach the document.
//
// It is reached from three paths, and must behave sensibly on all of them:
//   1. guideline analysed successfully  -> guideline values override defaults
//   2. no guideline supplied            -> defaults
//   3. download / extract / analysis failed -> defaults, with the reason recorded
//
// Anything the guideline does not state keeps its default. A guideline that
// mentions only a font must not silently reset the margins.

const DEFAULTS = {
  font: 'Times New Roman',
  fontSizePt: 12,
  pageSize: 'A4',
  lineSpacingPrelim: 1.5,
  lineSpacingChapters: 2.0,
  citationStyle: 'APA 7th Edition',
  alignment: 'justified',
  marginsInches: { top: 1, right: 1, bottom: 1, left: 1.5 },
};

const input = $input.first().json || {};

// The analyzer's structured output arrives under `output`; an error branch
// arrives with an `error` key and no rules at all.
const parsed = input.output && typeof input.output === 'object' ? input.output : null;
const errored = !!input.error;

const rules = JSON.parse(JSON.stringify(DEFAULTS));
const overrides = [];

function take(key, value, coerce) {
  if (value === null || value === undefined || value === '') return;
  const v = coerce ? coerce(value) : value;
  if (v === null || v === undefined || (typeof v === 'number' && !isFinite(v))) return;
  if (JSON.stringify(rules[key]) === JSON.stringify(v)) return;
  rules[key] = v;
  overrides.push(key);
}

const num = (v) => {
  const n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
  return isFinite(n) ? n : null;
};

if (parsed) {
  take('font', parsed.font);
  take('fontSizePt', parsed.fontSizePt, num);
  take('pageSize', parsed.pageSize, (v) => String(v).toUpperCase());
  take('lineSpacingPrelim', parsed.lineSpacingPrelim, num);
  take('lineSpacingChapters', parsed.lineSpacingChapters, num);
  take('citationStyle', parsed.citationStyle);
  take('alignment', parsed.alignment, (v) => String(v).toLowerCase());

  const m = parsed.marginsInches;
  if (m && typeof m === 'object') {
    const merged = Object.assign({}, DEFAULTS.marginsInches);
    let changed = false;
    for (const side of ['top', 'right', 'bottom', 'left']) {
      const v = num(m[side]);
      // sanity-bound: a "margin" of 0 or 9 inches is a parse artefact, not a rule
      if (v !== null && v >= 0.25 && v <= 3 && v !== merged[side]) { merged[side] = v; changed = true; }
    }
    if (changed) { rules.marginsInches = merged; overrides.push('marginsInches'); }
  }
}

// Guard the values the document generator divides and multiplies by.
if (!(rules.fontSizePt >= 8 && rules.fontSizePt <= 16)) rules.fontSizePt = DEFAULTS.fontSizePt;
if (!(rules.lineSpacingChapters >= 1 && rules.lineSpacingChapters <= 3)) rules.lineSpacingChapters = DEFAULTS.lineSpacingChapters;
if (!(rules.lineSpacingPrelim >= 1 && rules.lineSpacingPrelim <= 3)) rules.lineSpacingPrelim = DEFAULTS.lineSpacingPrelim;

const sub = $('Normalize Submission').first().json;

return [
  {
    json: {
      submission_id: sub.submission_id,
      project_title: sub.project_title,
      programme: sub.programme,
      faculty: sub.faculty,
      institution: sub.institution,
      student_name: sub.student_name,
      reg_number: sub.reg_number,
      supervisor: sub.supervisor,
      hod: sub.hod,
      study_location: sub.study_location,
      study_duration: sub.study_duration,
      student_email: sub.student_email,
      department: sub.department,
      degree: sub.degree,
      month_year: sub.month_year,
      format_rules: rules,
      guideline_status: parsed
        ? 'applied (' + (overrides.length ? overrides.join(', ') : 'no differences from default') + ')'
        : errored
        ? 'defaults used - guideline processing failed: ' + String(input.error).slice(0, 200)
        : 'defaults used - no guideline supplied',
    },
  },
];

// n8n Code node: "Assemble Document Input"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
//
// Joins the sub-workflow's chapters to the submission metadata and format rules,
// producing the single object the DOCX generator consumes.
//
// Keeping this join explicit is what lets docx-generator.js be unit-tested
// offline against a plain object (see ../ppw-thesis-chapters/test/).

const thesis = $input.first().json || {};
const ctx = $('Normalize Format Rules').first().json || {};

const report = thesis.citation_report || {};
const violations = report.violations || [];

return [
  {
    json: {
      meta: {
        project_title: ctx.project_title,
        programme: ctx.programme,
        faculty: ctx.faculty,
        institution: ctx.institution,
        student_name: ctx.student_name,
        reg_number: ctx.reg_number,
        supervisor: ctx.supervisor,
        hod: ctx.hod,
        department: ctx.department,
        degree: ctx.degree,
        month_year: ctx.month_year,
      },
      format_rules: ctx.format_rules,
      ch1: thesis.ch1,
      ch2: thesis.ch2,
      ch3: thesis.ch3,
      abstract: thesis.abstract,
      references: thesis.references,

      // carried through for the sheet, so a run with citation problems is
      // visible rather than silently shipped
      submission_id: ctx.submission_id,
      student_email: ctx.student_email,
      guideline_status: ctx.guideline_status,
      citation_count: report.unique_refs_cited || 0,
      unverified_count: violations.length,
      citation_violations: violations
        .map((v) => v.type + (v.ref_id ? ' ' + v.ref_id : '') + ' in ' + v.chapter)
        .join('; ')
        .slice(0, 480),
      evidence_stats: thesis.evidence_stats || {},
    },
  },
];

// n8n Code node: "Generate DOCX"
// MODE: Run Once for All Items   LANGUAGE: JavaScript
// Zero imports. Builds a valid .docx (OOXML inside a STORE-mode zip) by hand.
//
// Rewritten from the original in three ways that matter:
//
//  1. It consumes NAMED FIELDS. The original concatenated everything into one
//     blob and then regex-hunted for "# CHAPTER ONE" -- a header no prompt ever
//     emitted -- so Chapter One was silently dropped from every document.
//  2. Preliminary pages are BUILT FROM DATA, not generated by a model. Cover,
//     title, certification, approval, ToC, lists and abbreviations are pure
//     substitution or extraction, so there is nothing to parse and nothing to
//     hallucinate. The original's hardcoded fallback cover page -- which stamped
//     one specific IVU thesis title onto any document whose parse missed -- is
//     gone, along with the agent that made it necessary.
//  3. format_rules from the departmental guideline actually drive the styles.
//     Previously they were computed and then discarded.

// ------------------------------------------------------------------ input ----
const src = $input.first().json;

const meta = src.meta || {};
const rules = src.format_rules || {};
const ch = { ch1: src.ch1 || '', ch2: src.ch2 || '', ch3: src.ch3 || '' };
const abstractText = src.abstract || '';
const references = Array.isArray(src.references) ? src.references : [];

const FONT = rules.font || 'Times New Roman';
const SZ = Math.round((parseFloat(rules.fontSizePt) || 12) * 2); // half-points
const LINE_BODY = Math.round((parseFloat(rules.lineSpacingChapters) || 2.0) * 240);
const LINE_PRE = Math.round((parseFloat(rules.lineSpacingPrelim) || 1.5) * 240);
const MARGIN = (function () {
  const m = rules.marginsInches || {};
  const tw = (v, d) => Math.round((parseFloat(v) || d) * 1440);
  return { top: tw(m.top, 1), right: tw(m.right, 1), bottom: tw(m.bottom, 1), left: tw(m.left, 1.5) };
})();
const PAGE =
  String(rules.pageSize || 'A4').toUpperCase() === 'LETTER'
    ? { w: 12240, h: 15840 }
    : { w: 11906, h: 16838 };

// ------------------------------------------------------------------ CRC32 ----
function crc32(buf) {
  let table = crc32.t;
  if (!table) {
    table = crc32.t = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
      let c = i;
      for (let j = 0; j < 8; j++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      table[i] = c;
    }
  }
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) crc = table[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

// -------------------------------------------------------------- ZIP (STORE) ----
function createZip(files) {
  const entries = [];
  const local = [];
  let offset = 0;
  for (const f of files) {
    const nameB = Buffer.from(f.name, 'utf-8');
    const data = Buffer.from(f.content, 'utf-8');
    const crc = crc32(data);
    const lh = Buffer.alloc(30 + nameB.length);
    lh.writeUInt32LE(0x04034b50, 0);
    lh.writeUInt16LE(20, 4);
    lh.writeUInt32LE(crc, 14);
    lh.writeUInt32LE(data.length, 18);
    lh.writeUInt32LE(data.length, 22);
    lh.writeUInt16LE(nameB.length, 26);
    nameB.copy(lh, 30);
    entries.push({ nameB: nameB, data: data, crc: crc, offset: offset });
    local.push(Buffer.concat([lh, data]));
    offset += lh.length + data.length;
  }
  const cd = entries.map((e) => {
    const b = Buffer.alloc(46 + e.nameB.length);
    b.writeUInt32LE(0x02014b50, 0);
    b.writeUInt16LE(20, 4);
    b.writeUInt16LE(20, 6);
    b.writeUInt32LE(e.crc, 16);
    b.writeUInt32LE(e.data.length, 20);
    b.writeUInt32LE(e.data.length, 24);
    b.writeUInt16LE(e.nameB.length, 28);
    b.writeUInt32LE(e.offset, 42);
    e.nameB.copy(b, 46);
    return b;
  });
  const cdBuf = Buffer.concat(cd);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cdBuf.length, 12);
  eocd.writeUInt32LE(offset, 16);
  return Buffer.concat(local.concat([cdBuf, eocd]));
}

// ------------------------------------------------------------- XML helpers ----
function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    // control characters would make Word reject the part outright
    .replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g, '');
}

// **bold** and *italic* become real runs; the reference list relies on this
// for italic journal titles and volumes.
function makeRuns(text, forceBold) {
  let runs = '';
  const parts = String(text).split(/(\*\*[^*]+\*\*|\*[^*]+\*)/g);
  for (const part of parts) {
    if (!part) continue;
    const isBold = part.startsWith('**') && part.endsWith('**') && part.length > 4;
    const isItal = !isBold && part.startsWith('*') && part.endsWith('*') && part.length > 2;
    if (isBold) {
      runs +=
        '<w:r><w:rPr><w:b/><w:bCs/></w:rPr><w:t xml:space="preserve">' +
        esc(part.slice(2, -2)) +
        '</w:t></w:r>';
    } else if (isItal) {
      runs +=
        '<w:r><w:rPr><w:i/><w:iCs/></w:rPr><w:t xml:space="preserve">' +
        esc(part.slice(1, -1)) +
        '</w:t></w:r>';
    } else {
      runs +=
        '<w:r>' +
        (forceBold ? '<w:rPr><w:b/><w:bCs/></w:rPr>' : '') +
        '<w:t xml:space="preserve">' +
        esc(part) +
        '</w:t></w:r>';
    }
  }
  return runs;
}

function wp(text, o) {
  o = o || {};
  let p = '';
  if (o.heading) p += '<w:pStyle w:val="' + o.heading + '"/>';
  const jc = o.center ? 'center' : o.left ? 'left' : 'both';
  p += '<w:jc w:val="' + jc + '"/>';
  p +=
    '<w:spacing w:line="' +
    (o.line || LINE_BODY) +
    '" w:lineRule="auto" w:before="0" w:after="' +
    (o.after != null ? o.after : 120) +
    '"/>';
  if (o.pageBreak) p += '<w:pageBreakBefore/>';
  if (o.hangIndent) p += '<w:ind w:left="720" w:hanging="720"/>';
  if (o.bullet) p += '<w:numPr><w:ilvl w:val="0"/><w:numId w:val="1"/></w:numPr>';
  return '<w:p><w:pPr>' + p + '</w:pPr>' + (text ? makeRuns(text, o.bold) : '') + '</w:p>';
}

const blank = (n, o) => Array.from({ length: n }, () => wp('', o)).join('');

// --------------------------------------------------- markdown -> paragraphs ----
function renderBody(text, opts) {
  opts = opts || {};
  const line = opts.line || LINE_BODY;
  let xml = '';
  let buf = '';
  const flush = () => {
    if (buf.trim()) xml += wp(buf.trim(), { line: line });
    buf = '';
  };
  for (const rawLine of String(text).split('\n')) {
    const t = rawLine.trim();
    if (!t || t === '---' || t === '***') {
      flush();
      continue;
    }
    const h = t.match(/^(#{1,4})\s+(.*)$/);
    if (h) {
      flush();
      const depth = h[1].length;
      const style = depth === 1 ? 'Heading1' : depth === 2 ? 'Heading2' : 'Heading3';
      xml += wp(h[2], {
        bold: true,
        heading: style,
        center: depth === 1,
        left: depth > 1,
        line: line,
      });
      continue;
    }
    // "3.1 RESEARCH DESIGN" / "3.9.1 Validity" written without a hash
    const numbered = t.match(/^(\d+\.\d+(\.\d+)?)\s+(\S.*)$/);
    if (numbered && numbered[3].length < 90) {
      flush();
      xml += wp(t, {
        bold: true,
        heading: numbered[2] ? 'Heading3' : 'Heading2',
        left: true,
        line: line,
      });
      continue;
    }
    if (/^[-*•]\s+/.test(t)) {
      flush();
      xml += wp(t.replace(/^[-*•]\s+/, ''), { bullet: true, line: line });
      continue;
    }
    if (t.startsWith('|')) {
      flush();
      continue;
    }
    buf = buf ? buf + ' ' + t : t;
  }
  flush();
  return xml;
}

// ------------------------------------------------------------- extraction ----
const ALL_CHAPTERS = [ch.ch1, ch.ch2, ch.ch3].join('\n');

function extractCaptions(kind) {
  const re = new RegExp('\\b' + kind + '\\s+(\\d+\\.\\d+)\\s*[:.\\u2013-]\\s*([^\\n]{3,140})', 'gi');
  const out = [];
  const seen = {};
  let m;
  while ((m = re.exec(ALL_CHAPTERS)) !== null) {
    const num = m[1];
    if (seen[num]) continue;
    seen[num] = true;
    out.push({
      num: num,
      caption: m[2].replace(/\*/g, '').replace(/\s+/g, ' ').trim().replace(/[.\s]+$/, ''),
    });
  }
  return out.sort((a, b) => a.num.localeCompare(b.num, undefined, { numeric: true }));
}

// "Computed Tomography (CT)" -> CT. The initials of the expansion must line up
// with the abbreviation, which keeps ordinary parentheses out of the list.
function extractAbbreviations() {
  const re = /([A-Z][A-Za-z]+(?:[\s-][A-Za-z]+){0,5})\s*\(([A-Z][A-Z0-9]{1,7})\)/g;
  const map = {};
  const order = [];
  let m;
  while ((m = re.exec(ALL_CHAPTERS)) !== null) {
    const term = m[1].replace(/\s+/g, ' ').trim();
    const abbr = m[2];
    const initials = term
      .split(/[\s-]+/)
      .map((w) => w[0])
      .join('')
      .toUpperCase();
    if (!map[abbr] && initials.length >= 2 && abbr[0] === initials[0]) {
      map[abbr] = term;
      order.push(abbr);
    }
  }
  return order.sort().map((a) => [a, map[a]]);
}

